import{_ as i,C as r,o as t,c as o,a2 as s,b as h,w as a,a as p,E as d,a3 as l}from"./chunks/framework.Ci_RTJJ5.js";const v=JSON.parse('{"title":"05 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/05-prompt-assembly/overview.md","filePath":"chapters/05-prompt-assembly/overview.md"}'),c={name:"chapters/05-prompt-assembly/overview.md"};function u(m,e,b,g,k,y){const n=r("Mermaid");return t(),o("div",null,[e[1]||(e[1]=s(`<h1 id="_05-—-overview" tabindex="-1">05 — Overview <a class="header-anchor" href="#_05-—-overview" aria-label="Permalink to &quot;05 — Overview&quot;">​</a></h1><p><em>How prompt assembly works, and why it is a builder rather than a string. Read this before you write code.</em></p><hr><h2 id="the-request-has-a-shape" tabindex="-1">The request has a shape <a class="header-anchor" href="#the-request-has-a-shape" aria-label="Permalink to &quot;The request has a shape&quot;">​</a></h2><p>Every request is a list of messages, and the first one is special:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>  { &quot;role&quot;: &quot;system&quot;,  &quot;content&quot;: &quot;&lt;who you are, what the rules are&gt;&quot; },</span></span>
<span class="line"><span>  { &quot;role&quot;: &quot;user&quot;,    &quot;content&quot;: &quot;&lt;what the person asked&gt;&quot; },</span></span>
<span class="line"><span>  { &quot;role&quot;: &quot;assistant&quot;, ... },</span></span>
<span class="line"><span>  { &quot;role&quot;: &quot;tool&quot;, ... }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>The system message is the only part of the conversation the user never wrote. It is your agent&#39;s identity plus whatever the project says about itself. Everything after it is the conversation.</p>`,7)),(t(),h(l,null,{default:a(()=>[d(n,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20B%5B%22BasePrompt%3Cbr%2F%3Econstant%22%5D%20--%3E%20A%5B%22BuildSystemPrompt%22%5D%0A%20%20%20%20C%5B%22AgentsFile%3Cbr%2F%3Eworkspace%22%5D%20--%3E%20A%0A%20%20%20%20K%5B%22Contributor%3Cbr%2F%3Echapter%2009%3A%20skills%22%5D%20-.-%3E%20A%0A%20%20%20%20A%20--%3E%20S%5B%22system%20message%22%5D%0A%20%20%20%20U%5B%22user%20prompt%22%5D%20--%3E%20H%5B%22history%22%5D%0A%20%20%20%20S%20--%3E%20H%0A%20%20%20%20H%20--%3E%20L%5B%22RunLoop%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<h2 id="why-a-builder-and-not-a-format-string" tabindex="-1">Why a builder and not a format string <a class="header-anchor" href="#why-a-builder-and-not-a-format-string" aria-label="Permalink to &quot;Why a builder and not a format string&quot;">​</a></h2><p>A single <code>fmt.Sprintf</code> works until the second thing wants to contribute. Then it becomes a format string with six placeholders and a <code>strings.Join</code> in the middle, and every new section edits the same function.</p><p>The interface is small:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Contributor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Contribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>and the builder is a fold over the contributors. Chapter 09 adds skills by implementing this interface. It does not edit the loop, the provider, or the builder.</p><p>That is the point of the seam: <strong>later chapters add files, not edits.</strong></p><h2 id="the-prefix-must-be-stable" tabindex="-1">The prefix must be stable <a class="header-anchor" href="#the-prefix-must-be-stable" aria-label="Permalink to &quot;The prefix must be stable&quot;">​</a></h2><p>Providers cache the beginning of a request. If the prefix matches the previous request byte for byte, the computation is reused, and the response is cheaper and faster. If one character changes, the cache misses.</p><p>So the system message must contain nothing that varies between runs:</p><table tabindex="0"><thead><tr><th>Allowed</th><th>Not allowed</th></tr></thead><tbody><tr><td>a constant base instruction</td><td>a timestamp</td></tr><tr><td>file contents</td><td>a random session id</td></tr><tr><td>absolute file paths</td><td>map iteration order</td></tr><tr><td>a fixed section order</td><td>the current working directory as a sentence</td></tr></tbody></table><p>Absolute paths are allowed because they are stable for a given workspace. Map iteration is not, which is the bug this chapter&#39;s stability case catches: two runs over the same files must produce the same bytes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  run 1:  base + &quot;## /w/AGENTS.md&quot; + rules      ─┐</span></span>
<span class="line"><span>  run 2:  base + &quot;## /w/AGENTS.md&quot; + rules      ─┴─ cache hit</span></span>
<span class="line"><span>  run 3:  base + timestamp + rules              ─── cache miss</span></span></code></pre></div><h2 id="discovery-walks-up-rendering-runs-down" tabindex="-1">Discovery walks up, rendering runs down <a class="header-anchor" href="#discovery-walks-up-rendering-runs-down" aria-label="Permalink to &quot;Discovery walks up, rendering runs down&quot;">​</a></h2><p>A monorepo keeps rules at the root. A package adds its own. The agent should see both, and when they disagree, the closer file should win.</p><p>Order is how you express that without a merge algorithm:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  /repo/AGENTS.md          outer rules          rendered first</span></span>
<span class="line"><span>  /repo/pkg/AGENTS.md      package rules        rendered last</span></span></code></pre></div><p>A model reading top to bottom reaches the most specific rule at the end, which is where a final instruction carries the most weight. Discovery therefore walks upward, then reverses before rendering.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  cwd = /repo/pkg</span></span>
<span class="line"><span>  walk up:  /repo/pkg/AGENTS.md   ✓</span></span>
<span class="line"><span>            /repo/AGENTS.md       ✓</span></span>
<span class="line"><span>            /AGENTS.md            (missing)</span></span>
<span class="line"><span>  reverse:  [/repo/AGENTS.md, /repo/pkg/AGENTS.md]</span></span></code></pre></div><p>The walk is bounded, because a file at <code>/</code> is not project instructions.</p><h2 id="empty-means-absent" tabindex="-1">Empty means absent <a class="header-anchor" href="#empty-means-absent" aria-label="Permalink to &quot;Empty means absent&quot;">​</a></h2><p>A file that exists and contains only whitespace is not an instruction. Rendering its heading produces this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Project instructions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## /repo/AGENTS.md</span></span>
<span class="line"><span>                              ← nothing</span></span></code></pre></div><p>The model reads a heading with no content and concludes that instructions existed and were withheld. Dropping the section is more honest and keeps the prefix shorter.</p><p>The same rule applies to the whole section: if no file contributed anything, do not emit <code># Project instructions</code> at all.</p><h2 id="what-assembly-must-not-do" tabindex="-1">What assembly must not do <a class="header-anchor" href="#what-assembly-must-not-do" aria-label="Permalink to &quot;What assembly must not do&quot;">​</a></h2><p>It must not touch the user&#39;s text. The prompt the person typed arrives at the model unchanged, as the second message. A wrapper added during assembly is a wrapper the user cannot see and cannot debug.</p><table tabindex="0"><thead><tr><th>Layer</th><th>May change</th><th>Must not change</th></tr></thead><tbody><tr><td>system message</td><td>assembled from contributors</td><td>nothing varies between runs</td></tr><tr><td>user message</td><td>nothing</td><td>the exact text the person typed</td></tr></tbody></table><h2 id="where-the-real-implementations-go-further" tabindex="-1">Where the real implementations go further <a class="header-anchor" href="#where-the-real-implementations-go-further" aria-label="Permalink to &quot;Where the real implementations go further&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>pi</th><th>crush</th></tr></thead><tbody><tr><td>Context file discovery</td><td><code>docs/configuration.md</code>, project trust first</td><td><code>internal/discover/</code></td></tr><tr><td>Skill advertising</td><td>description-only until invoked</td><td><code>internal/skills/</code></td></tr><tr><td>Prompt cache control</td><td>provider-specific cache markers</td><td>provider adapters</td></tr></tbody></table><p>Two things they add that this chapter does not: a trust decision before loading project files, and per-contributor sizes. Both are policy; the seam is the same.</p><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>Why is the system message a fold over contributors rather than one format string? <em>(Why a builder and not a format string)</em></li><li>Name three things that must never appear in it. <em>(The prefix must be stable)</em></li><li>Discovery goes up and rendering goes down. Why? <em>(Discovery walks up, rendering runs down)</em></li><li>What does an empty AGENTS.md render as if you do not special-case it, and why is that bad? <em>(Empty means absent)</em></li><li>Which message is allowed to be rewritten, and which is not? <em>(What assembly must not do)</em></li></ol>`,32))])}const w=i(c,[["render",u]]);export{v as __pageData,w as default};
